	"core/common.glsl": "precision highp float;\nprecision highp int;\nprecision highp sampler2D;\n\nconst float Tau = 6.28318530718;\nconst float Pi = 3.14159265359;\nconst int RampResolution = 256;\nconst int DataWidth = 256;\n\nuniform sampler2D uData;\n\nstruct Fragment {\n    vec2 uv;\n    vec2 point;\n    vec2 size;\n    vec2 tilt;\n};\n\nstruct Layer {\n    vec4 a;\n    vec4 b;\n    vec4 c;\n    vec4 d;\n    vec2 range;\n    float opacity;\n    float time;\n    float phase;\n    int kind;\n    int blend;\n    int tile;\n    int space;\n    int ramp;\n    int data;\n    int count;\n    int surface;\n};\n\nfloat saturate(float value) {\n    return clamp(value, 0.0, 1.0);\n}\n\nvec2 saturate(vec2 value) {\n    return clamp(value, 0.0, 1.0);\n}\n\nvec3 saturate(vec3 value) {\n    return clamp(value, 0.0, 1.0);\n}\n\nvec4 fetchData(int index) {\n    return texelFetch(uData, ivec2(index % DataWidth, index / DataWidth), 0);\n}\n\nLayer loadLayer(int index) {\n    int base = index * 8;\n    vec4 timing = fetchData(base + 4);\n    vec4 modes = fetchData(base + 5);\n    vec4 offsets = fetchData(base + 6);\n    vec4 extra = fetchData(base + 7);\n\n    Layer layer;\n    layer.a = fetchData(base);\n    layer.b = fetchData(base + 1);\n    layer.c = fetchData(base + 2);\n    layer.d = fetchData(base + 3);\n    layer.range = timing.xy;\n    layer.opacity = timing.z;\n    layer.time = timing.w;\n    layer.phase = modes.x;\n    layer.kind = int(modes.y + 0.5);\n    layer.blend = int(modes.z + 0.5);\n    layer.tile = int(modes.w + 0.5);\n    layer.space = int(offsets.x + 0.5);\n    layer.ramp = int(offsets.y + 0.5);\n    layer.data = int(offsets.z + 0.5);\n    layer.count = int(offsets.w + 0.5);\n    layer.surface = int(extra.x + 0.5);\n    return layer;\n}\n\nvec2 rotate(vec2 p, float angle) {\n    float s = sin(angle);\n    float c = cos(angle);\n    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat tileValue(float t, int tile) {\n    if (tile == 1) {\n        return fract(t);\n    }\n    if (tile == 2) {\n        return 1.0 - abs(fract(t * 0.5) * 2.0 - 1.0);\n    }\n    return t;\n}\n\nvec4 sampleRamp(Layer layer, float t) {\n    float span = max(layer.range.y - layer.range.x, 1e-5);\n    float x = (t + layer.phase - layer.range.x) / span;\n    if (layer.tile == 3 && (x < 0.0 || x > 1.0)) {\n        return vec4(0.0);\n    }\n    x = saturate(tileValue(x, layer.tile));\n    float position = x * float(RampResolution - 1);\n    int index = min(int(position), RampResolution - 2);\n    return mix(fetchData(layer.ramp + index), fetchData(layer.ramp + index + 1), position - float(index));\n}\n\nvec3 srgbEncode(vec3 color) {\n    vec3 c = saturate(color);\n    return mix(1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, c * 12.92, lessThanEqual(c, vec3(0.0031308)));\n}\n\nvec3 oklabToLinear(vec3 lab) {\n    float l = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;\n    float m = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;\n    float s = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;\n    l = l * l * l;\n    m = m * m * m;\n    s = s * s * s;\n    return vec3(\n        4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,\n        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,\n        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s\n    );\n}\n\nvec4 resolveColor(vec4 premultiplied, int space) {\n    float alpha = saturate(premultiplied.a);\n    if (alpha <= 1e-5) {\n        return vec4(0.0);\n    }\n    vec3 value = premultiplied.rgb / premultiplied.a;\n    vec3 encoded = space == 0 ? saturate(value) : srgbEncode(space == 1 ? value : oklabToLinear(value));\n    return vec4(encoded * alpha, alpha);\n}\n\nfloat hash(vec2 p) {\n    vec3 q = fract(vec3(p.xyx) * 0.1031);\n    q += dot(q, q.yzx + 33.33);\n    return fract((q.x + q.y) * q.z);\n}\n\nfloat cellHash(vec2 cell) {\n    vec2 q = fract(cell * vec2(0.1031, 0.1030) + vec2(0.217, 0.613));\n    q += dot(q, q.yx + 19.19);\n    return fract((q.x + q.y) * q.y * 3.7 + sin(dot(cell, vec2(12.9898, 78.233))) * 0.5);\n}\n\nfloat interleavedNoise(vec2 p) {\n    return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));\n}\n\nvec3 thinFilm(float phase) {\n    return 0.5 - 0.5 * cos(Tau * phase * vec3(1.0, 1.226, 1.413));\n}\n\nvec3 unpremultiply(vec4 color) {\n    return color.rgb / max(color.a, 1e-4);\n}\n\n",
	"core/composite.glsl": "uniform vec2 uSize;\nuniform vec2 uTilt;\nuniform float uScale;\nuniform float uDither;\nuniform float uGrain;\nuniform int uLayerCount;\nuniform int uMaskMode;\nuniform vec2 uBorder;\nuniform sampler2D uMask;\n\nin vec2 vUv;\n\nout vec4 fragColor;\n\nfloat roundedBox(vec2 point, vec2 extent, float radius) {\n    vec2 q = abs(point) - extent + radius;\n    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;\n}\n\nfloat borderCoverage(vec2 point, vec2 size) {\n    vec2 extent = size * 0.5;\n    vec2 p = point - extent;\n    float width = max(uBorder.x, 0.0);\n    float radius = min(max(uBorder.y, 0.0), min(extent.x, extent.y));\n    float outer = saturate(0.5 - roundedBox(p, extent, radius) * uScale);\n    vec2 innerExtent = extent - width;\n    if (innerExtent.x <= 0.0 || innerExtent.y <= 0.0) {\n        return outer;\n    }\n    float innerRadius = min(max(radius - width, 0.0), min(innerExtent.x, innerExtent.y));\n    return outer * saturate(0.5 + roundedBox(p, innerExtent, innerRadius) * uScale);\n}\n\nvoid main() {\n    Fragment f;\n    f.uv = vUv;\n    f.size = uSize;\n    f.point = vUv * uSize;\n    f.tilt = uTilt;\n\n    vec4 result = vec4(0.0);\n    for (int i = 0; i < uLayerCount; i++) {\n        Layer layer = loadLayer(i);\n        vec4 color = clamp(evaluateLayer(f, layer), 0.0, 1.0);\n        color.rgb = min(color.rgb, vec3(color.a));\n        color *= layer.opacity;\n#ifdef SOURCE_OVER\n        result = color + result * (1.0 - color.a);\n#else\n        result = composite(result, color, layer.blend);\n#endif\n    }\n\n    if (uMaskMode == 1) {\n        result *= texture(uMask, vUv).a;\n    } else if (uMaskMode == 2) {\n        result *= borderCoverage(f.point, uSize);\n    }\n\n    vec3 rgb = result.rgb;\n    if (uGrain > 0.0) {\n        rgb += (hash(floor(gl_FragCoord.xy / uScale)) - 0.5) * uGrain * 0.2 * result.a;\n    }\n    rgb += (interleavedNoise(gl_FragCoord.xy) - 0.5) * (uDither / 255.0) * result.a;\n    fragColor = vec4(clamp(rgb, 0.0, result.a), result.a);\n}\n",
